def choose_move(observation):
    def clamp_step(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def pos2(v, default=(0, 0)):
        try:
            if isinstance(v, (list, tuple)) and len(v) >= 2:
                return int(v[0]), int(v[1])
        except:
            pass
        return default

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(src, dst):
        return [clamp_step(dst[0] - src[0]), clamp_step(dst[1] - src[1])]

    def step_away(src, dst):
        return [clamp_step(src[0] - dst[0]), clamp_step(src[1] - dst[1])]

    def nearest(items, src):
        best = None
        best_d = None
        for it in items or []:
            p = pos2(it, None)
            if p is None:
                continue
            d = dist(src, p)
            if best is None or d < best_d:
                best = p
                best_d = d
        return best

    def farthest(items, src):
        best = None
        best_d = None
        for it in items or []:
            p = pos2(it, None)
            if p is None:
                continue
            d = dist(src, p)
            if best is None or d > best_d:
                best = p
                best_d = d
        return best

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos2(observation.get("self_position", (0, 0)))
    ox, oy = pos2(observation.get("opponent_position", (sx, sy)))
    self_pos = (sx, sy)
    opp_pos = (ox, oy)

    w = observation.get("grid_width", observation.get("width", 0))
    h = observation.get("grid_height", observation.get("height", 0))
    try:
        w = int(w)
    except:
        w = 0
    try:
        h = int(h)
    except:
        h = 0

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)
        corners = [(0, 0), (0, max(0, h - 1)), (max(0, w - 1), 0), (max(0, w - 1), max(0, h - 1))]
        target = farthest(corners, opp_pos)
        if target is None:
            return step_away(self_pos, opp_pos)
        return step_toward(self_pos, target)

    if env == "territory_control":
        targets = (
            observation.get("unclaimed_cells")
            or observation.get("neutral_cells")
            or observation.get("opponent_territory")
            or observation.get("frontier_cells")
            or []
        )
        target = nearest(targets, self_pos)
        if target is not None:
            return step_toward(self_pos, target)

        # If nothing explicit, pressure opponent or drift to center/frontier.
        if ox != sx or oy != sy:
            return step_toward(self_pos, opp_pos)
        cx = (w - 1) // 2 if w > 0 else sx
        cy = (h - 1) // 2 if h > 0 else sy
        return step_toward(self_pos, (cx, cy))

    resources = observation.get("resources") or observation.get("resource_positions") or observation.get("resource_cells") or []
    target = nearest(resources, self_pos)
    if target is not None:
        return step_toward(self_pos, target)

    # No resource visible: move away from opponent, otherwise toward center.
    if ox != sx or oy != sy:
        away = step_away(self_pos, opp_pos)
        if away != [0, 0]:
            return away

    cx = (w - 1) // 2 if w > 0 else sx
    cy = (h - 1) // 2 if h > 0 else sy
    return step_toward(self_pos, (cx, cy))

